//autogenerated:yes
//nolint:revive,govet,errcheck
package development_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/development"
)

func TestEnum_GPS_SPOOFING_STATE(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.GPS_SPOOFING_STATE
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.GPS_SPOOFING_STATE_UNKNOWN.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.GPS_SPOOFING_STATE
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.GPS_SPOOFING_STATE_UNKNOWN, dec)
	})
}
